const recordLoginFailure = `-- name: RecordLoginFailure :one
INSERT INTO login_throttle (document_key, failures, first_failure_at, updated_at)
VALUES ($1, 1, $2::timestamptz, $2::timestamptz)
ON CONFLICT (document_key) DO UPDATE SET
    failures         = CASE WHEN login_throttle.first_failure_at < $3 THEN 1 ELSE login_throttle.failures + 1 END,
    first_failure_at = CASE WHEN login_throttle.first_failure_at < $3 THEN $2::timestamptz ELSE login_throttle.first_failure_at END,
    updated_at       = $2::timestamptz
RETURNING document_key, failures, first_failure_at, locked_until, updated_at
`

type RecordLoginFailureParams struct {
	DocumentKey []byte
	At          time.Time
	WindowStart time.Time
}

// Suma un fallo; la ventana se reinicia si el primer fallo es más viejo que @window_start.
func (q *Queries) RecordLoginFailure(ctx context.Context, arg RecordLoginFailureParams) (LoginThrottle, error) {
	row := q.db.QueryRow(ctx, recordLoginFailure, arg.DocumentKey, arg.At, arg.WindowStart)
	var i LoginThrottle
	err := row.Scan(
		&i.DocumentKey,
		&i.Failures,
		&i.FirstFailureAt,
		&i.LockedUntil,
		&i.UpdatedAt,
	)
	return i, err
}

