const validatingEnablement = `-- name: ValidatingEnablement :one

SELECT e.tenant_id, e.person_public_id, e.enabled_at, t.tenant_public_id, t.display_name, t.support, t.sms_enabled
FROM enablements e
JOIN tenants t ON t.id = e.tenant_id
WHERE e.document_type = $1 AND e.document_number = $2
  AND e.status = 'enabled' AND t.is_enabled
ORDER BY e.enabled_at, e.tenant_id
LIMIT 1
`

type ValidatingEnablementParams struct {
	DocumentType   string
	DocumentNumber string
}

type ValidatingEnablementRow struct {
	TenantID       uuid.UUID
	PersonPublicID uuid.UUID
	EnabledAt      time.Time
	TenantPublicID uuid.UUID
	DisplayName    string
	Support        json.RawMessage
	SmsEnabled     bool
}

// Identidad del canal (US2): cuentas, aceptaciones, dispositivos, sesiones, códigos, freno de ingresos y passkeys.
// La entidad validadora (D5, FR-017): la habilitación 'enabled' de menor enabled_at del documento, en una cooperativa con
// el canal encendido.
func (q *Queries) ValidatingEnablement(ctx context.Context, arg ValidatingEnablementParams) (ValidatingEnablementRow, error) {
	row := q.db.QueryRow(ctx, validatingEnablement, arg.DocumentType, arg.DocumentNumber)
	var i ValidatingEnablementRow
	err := row.Scan(
		&i.TenantID,
		&i.PersonPublicID,
		&i.EnabledAt,
		&i.TenantPublicID,
		&i.DisplayName,
		&i.Support,
		&i.SmsEnabled,
	)
	return i, err
}
